draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // character
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 20);
  ctx.lineTo(W/2, H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 30);
  ctx.lineTo(W/2 - 20, H/2 + 40);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 30);
  ctx.lineTo(W/2 + 20, H/2 + 40);
  ctx.stroke();

  // sad face
  ctx.beginPath();
  ctx.arc(W/2 - 10, H/2 - 10, 5, 0, Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W/2 + 10, H/2 - 10, 5, 0, Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 15, H/2);
  ctx.lineTo(W/2 + 15, H/2);
  ctx.stroke();

  // waving arm
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 30);
  ctx.lineTo(W/2 - 30 + 20 * Math.sin(t), H/2 + 50);
  ctx.stroke();

  // falling tear
  ctx.beginPath();
  ctx.arc(W/2 - 20 + 10 * Math.sin(t), H/2 + 60 + 10 * Math.cos(t), 5, 0, 2 * Math.PI);
  ctx.fill();

  ctx.restore();
}
